{
  "name": "Opentrons 温度模块",
  "name_en": "Opentrons Temperature Module",
  "manufacturer": "Opentrons",
  "description": "Opentrons 温度模块是一种用于实验室自动化平台的温控附件，可对样品板或其他小型实验容器进行加热或冷却并维持设定温度，常用于样品孵育、试剂保冷及温度敏感实验流程。",
  "description_en": "The Opentrons Temperature Module is a temperature-control accessory for laboratory automation platforms. It heats or cools microplates or other small lab containers and maintains a set temperature for sample incubation, reagent cooling, and other temperature-sensitive workflows.",
  "tag_hints": [
    "temperature control",
    "sample incubation",
    "active cooling",
    "microplate heating",
    "lab automation module",
    "reagent cooling"
  ],
  "actions": [
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取是否支持主动制冷",
      "description_en": "get whether active cooling is supported"
    },
    {
      "action_name": "auto-serial",
      "description": "获取设备序列号",
      "description_en": "get the device serial number"
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备当前配置与状态信息",
      "description_en": "serialize the current device configuration and state"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度",
      "description_en": "set the target temperature"
    },
    {
      "action_name": "auto-deactivate",
      "description": "停用温控并停止加热或制冷",
      "description_en": "deactivate temperature control and stop heating or cooling"
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度",
      "description_en": "get the current temperature"
    }
  ]
}

